create or replace function public.get_gateway_health(p_gateway_id text,p_window_minutes integer default 60) returns jsonb language sql security definer set search_path=public as $$ with ops as (select count(*) total,count(*) filter(where status in ('success','approved','completed')) ok,count(*) filter(where status in ('failed','error','declined')) bad,coalesce(avg(nullif((response_meta->>'response_time_ms')::numeric,0)),0) avg_ms from gateway_operation_logs where gateway_id=p_gateway_id and created_at>=now()-make_interval(mins=>greatest(1,p_window_minutes))), tx as (select count(*) total,count(*) filter(where status='approved') approved,count(*) filter(where status in ('failed','declined')) failed from gateway_transactions where gateway_id=p_gateway_id and created_at>=now()-make_interval(mins=>greatest(1,p_window_minutes))) select jsonb_build_object('window_minutes',greatest(1,p_window_minutes),'operations',jsonb_build_object('total',ops.total,'success',ops.ok,'failed',ops.bad,'success_rate',case when ops.total=0 then null else round((ops.ok::numeric/ops.total)*100,2) end,'avg_response_ms',round(ops.avg_ms,2)),'transactions',jsonb_build_object('total',tx.total,'approved',tx.approved,'failed',tx.failed,'approval_rate',case when tx.total=0 then null else round((tx.approved::numeric/tx.total)*100,2) end)) from ops,tx $$; revoke all on function public.get_gateway_health(text,integer) from public,anon,authenticated; grant execute on function public.get_gateway_health(text,integer) to service_role;